#include <stdio.h> // 提供 printf 的声明
#include <string.h> // 提供 strlen 和 strcmp 的声明

int main(void) // 程序入口
{ // 先观察一个固定的英文单词
    char team[] = "goal"; // 四个字母后自动带有字符串结束标记
    printf("name=%s\n", team); // 按字符串输出队名
    printf("length=%zu\n", strlen(team)); // 输出结束标记之前的字节数
    printf("same=%d\n", strcmp(team, "goal") == 0); // 内容相等时比较返回零
    return 0; // 正常结束
} // 主函数结束
